  /**
   * dependenciaActions::executeReadFileTrdMasiva()
   * Accion para funcionalidad leer datos del archivo de excel, previa a la migracion masiva de TRDs
   * @return
   */
  public function executeReadFileTrdMasiva()
  {
    $currentForm="TRD_MIGRACION_MASIVA";
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
    if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
        $this->cod_msg = 1;
        $this->msg_error = "Esta funcionalidad no esta permitida";
    }
    //*******************************************************************************************
    if ($this->getRequest()->hasFiles() && $this->getRequest()->getFileName('file')){ 
      try {
        $file_vars = pathinfo($this->getRequest()->getFileName('file'));
        //*****************************************************************************************
        $dirRaiz    = ParametroPeer::retrieveByPk(9)->getValortexto();
        $dirTmp     = ParametroPeer::retrieveByPk(65)->getValortexto();
        $directorio_tmp = simad_util::createPath($dirRaiz.DIRECTORY_SEPARATOR.$dirTmp);
        //*****************************************************************************************
        $util_simad = new simad_util();
        $extension_file = $file_vars['extension'];
        //*****************************************************************************************
        $info_file = new SplFileInfo($this->getRequest()->getFileName('file'));
        $cleanfilename = $util_simad->clean_name_fileinfo($info_file);//limpiar el nombre del archivo
        $file_name = simad_util::uniquename($directorio_tmp,sha1($cleanfilename.time()),".".$extension_file);//validar uniquename    		
        $inputFileName = $directorio_tmp.DIRECTORY_SEPARATOR.$file_name;
        $this->getRequest()->moveFile('file', $inputFileName);
        //*****************************************************************************************
        $listVars = DependenciaPeer::readFileComCombined($inputFileName);
      } catch (PropelException $th) {
        $inputFileName = null;
        $listVars = array();
      } catch (\Exception $th) {
        //throw $th;
      } catch (\Throwable $th) {
        //throw $th;
      }
      //*****************************************************************************************
      $this->inputFileName = basename($inputFileName);
      $this->headerList = isset($listVars['headerList']) ? $listVars['headerList'] : null;
      $this->sheetData = isset($listVars['sheetData']) ? $listVars['sheetData'] : null;
      $this->sheetDataSerialize = isset($listVars['sheetDataSerialize']) ? $listVars['sheetDataSerialize'] : null;
      $this->cod_msg = isset($listVars['cod_msg']) ? $listVars['cod_msg'] : null;
      $this->msg_error = isset($listVars['msg_error']) ? $listVars['msg_error'] : null;
    }
    else
    {
        $this->cod_msg = 1;
        $this->msg_error = "Debe seleccionar el archivo que contiene las registros para importar";
    }
  }

  /**
   * dependenciaActions::executeVerifyTrdBatchData()
   * accion para verificar la informacion enviada en el excel
   * @return
   */
  public function executeVerifyTrdBatchData()
  {
    $currentForm="TRD_MIGRACION_MASIVA";
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
    if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
        $status = 400;
        $message = "Esta funcionalidad no esta permitida";
        //***************************************************************************************
        $this->getResponse()->setContentType('application/json');
        $response_info = array('status' => $status, 'message' => $message, 'comIdLote' => null);
        return $this->renderText(json_encode($response_info));
    }
    //*******************************************************************************************
    $sheetData = trim($this->getRequestParameter('sheetData')) ?: 0;
    $simad_util = new simad_util();
    $data = $simad_util->getArrayUnSerialize($sheetData);
    //******************************************************************************************
    $list_nrow = DependenciaPeer::getRowsFilesToArray($data,$usuariologuiado);
    $elist_msg = DependenciaPeer::getIsValidByIdBatch($list_nrow);
    //*******************************************************************************************
    $this->getResponse()->setContentType('application/json');
    $response_info = array('status' => (count($elist_msg) ? 400 : 200), 'message' => $elist_msg, 'comIdLote' => null);
    return $this->renderText(json_encode($response_info));
  }

  /**
  * dependenciaActions::executeUpdateImportBatch()
  * Radicar comunicaciones externas recibidas masivas con archivo plano
  * @return
  */
  public function executeUpdateImportBatch()
  {
    $currentForm="TRD_MIGRACION_MASIVA";
		$usuariologuiado = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
    //*******************************************************************************************
    if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
        $status = 400;
        $message = "Esta funcionalidad no esta permitida";
        //***************************************************************************************
        $this->getResponse()->setContentType('application/json');
        $response_info = array('status' => $status, 'message' => $message, 'comIdLote' => null);
        return $this->renderText(json_encode($response_info));
    }
    //*******************************************************************************************
    $parameters['sheetData'] = trim($this->getRequestParameter('sheetData')) ?: 0;
    $parameters['fileuploadtmp'] = trim($this->getRequestParameter('fileuploadtmp')) ? trim($this->getRequestParameter('fileuploadtmp')) : null;
    $parameters['filedocsupload'] = trim($this->getRequestParameter('filedocsupload')) ? trim($this->getRequestParameter('filedocsupload')) : null;
    $parameters['dataufile'] = trim($this->getRequestParameter('dataufile')) ? trim($this->getRequestParameter('dataufile')) : null;
    $parameters['comIdLote'] = trim($this->getRequestParameter('comIdLote')) ? trim($this->getRequestParameter('comIdLote')) : null;
    //*******************************************************************************************
    $dirRaiz    = ParametroPeer::retrieveByPk(9)->getValortexto();
    $dirTmp     = ParametroPeer::retrieveByPk(65)->getValortexto();
    $directorio_tmp = simad_util::createPath($dirRaiz.DIRECTORY_SEPARATOR.$dirTmp);
    $inputFileName = $directorio_tmp.DIRECTORY_SEPARATOR.$parameters['fileuploadtmp'];
    //*******************************************************************************************
    try{
      $data = DependenciaPeer::readFileComCombined($inputFileName);
      $list_nrow = DependenciaPeer::getRowsFilesToArray($data['sheetData'],$usuariologuiado);
      //*****************************************************************************************
      $max_time = ini_get("max_execution_time");
      ini_set('max_execution_time', 900);
      $ilsit_error = array();
      //*****************************************************************************************
      $index = 1;
      foreach ($list_nrow as $row) {
        $response_create = DependenciaPeer::addNewTrd($row);
        if($response_create['isError']){
          $ilsit_error[] = sprintf("Error creando, %s fila %s",$response_create['message'],$index);
        }
        //***************************************************************************************
        $index++;
      }
      //*****************************************************************************************
      ini_set('max_execution_time', $max_time);
      //*****************************************************************************************
      if(count($ilsit_error)){
        $error_message = implode(";",$ilsit_error);
        $response_info = array('status' => 301, 'message' => "Ocurrio un error y algunos registros no se importaron, ".$error_message, 'comIdLote' => null);
      }else{
        $response_info = array('status' => 200, 'message' => "Todos los registros se importaron exitosamente", 'comIdLote' => null);
      }
    } catch (PropelException $th) {
      $response_info = array('status' => 400, 'message' => "Error de acceso a la base de datos", 'comIdLote' => null);
    } catch (\IOException $th) {
      $response_info = array('status' => 402, 'message' => "Error de acceso al archivo de datos", 'comIdLote' => null);
    } catch (\Exception $th) {
      $response_info = array('status' => 500, 'message' => "Error interno de la aplicacion", 'comIdLote' => null);
    } catch (\Throwable $th) {
      $response_info = array('status' => 501, 'message' => "Error interno del servidor", 'comIdLote' => null);
    }
    //*******************************************************************************************
    $this->getResponse()->setContentType('application/json');
    return $this->renderText(json_encode($response_info));
  }

  public function executeValidate()
  {
  	$dependencia = DependenciaPeer::retrieveByPK($this->getRequestParameter('dependencia_id'));
    $dependencia_anterior = $dependencia->copy();
    //******************************************************************************************
    $dependencia->setEsActual(empty($dependencia->getEsActual()) ? 1 : 0);
    $dependencia->save();
    //******************************************************************************************
    DependenciaPeer::guardarAuditoria($dependencia_anterior,$dependencia);
    //******************************************************************************************
    $this->dependencia = $dependencia;
  	$this->forward404Unless($dependencia);
  }

