  public function executeList()
  {
  	$this->verificaPrilegio("TRDdependencia/list");
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $oficinaproductora_id = "";
    $procesos_id = "";
    /************************************************************************************************/
    $param_admin_trd = ParametroPeer::retrieveByPK(61)->getValornumerico();
    /************************************************************************************************/
    $entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
    $regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
    $usuario_object = UsuarioPeer::retrieveByPK($usuariologuiado);
    $dependencia_conectado = $usuario_object->getDependenciaId();
    /********************************************************************************************/
    if($this->getRequestParameter('dependencia_id') && $param_admin_trd == 2)
    {
        $dependencia = DependenciaPeer::retrieveByPK($this->getRequestParameter('dependencia_id'));
        $oficinaproductora_id = $dependencia->getOficinaproductoraId();
        $procesos_id = $dependencia->getOficinaProductora()->getProcesosId();
    }
    elseif($this->getRequestParameter('oficinaproductora_id'))
    {
        $oficinaproductora_id = $this->getRequestParameter('oficinaproductora_id');
        $oficina_productora = OficinaProductoraPeer::retrieveByPK($oficinaproductora_id);
        $procesos_id = $oficina_productora->getProcesosId();        
    }    		
    /************************************************************************************************/
    if($procesos_id || $param_admin_trd == 1)
    {
      	$c = new Criteria();
        $c->setDistinct();
        $this->parametros = "a=1";
        
        if($param_admin_trd == 2){
    	 	$c->add(DependenciaPeer::OFICINAPRODUCTORA_ID,$oficinaproductora_id);
    		$this->parametros.="&oficinaproductora_id=".$oficinaproductora_id;
        }
        
        if($this->getRequestParameter('nombre')){
    	 	$c->add(DependenciaPeer::NOMBRE,'%'.$this->getRequestParameter('nombre').'%',Criteria::LIKE);		
    		$this->parametros.="&nombre=".$this->getRequestParameter('nombre');			 	
        }
        
        if($this->getRequestParameter('codigo')){
    	 	$c->add(DependenciaPeer::CODIGO,'%'.$this->getRequestParameter('codigo').'%',Criteria::LIKE);		
    		$this->parametros.="&codigo=".$this->getRequestParameter('codigo');			 	
        }
        
        if($this->getRequestParameter('entidad_id')){
    	 	$c->add(DependenciaPeer::ENTIDAD_ID,$this->getRequestParameter('entidad_id'));		
    		$this->parametros.="&entidad_id=".$this->getRequestParameter('entidad_id');			 	
        }
        
        if($this->getRequestParameter('subserie_id')){
            $c->addJoin(DependenciaPeer::DEPENDENCIA_ID,SeriePeer::DEPENDENCIA_ID);
            $c->addJoin(SeriePeer::SERIE_ID,SubseriePeer::SERIE_ID);
    	 	$c->add(SubseriePeer::SUBSERIE_ID,$this->getRequestParameter('subserie_id'));		
    		$this->parametros.="&subserie_id=".$this->getRequestParameter('subserie_id');			 	
        }
        
        if($this->getRequestParameter('serie_id')){
            $c->addJoin(DependenciaPeer::DEPENDENCIA_ID,SeriePeer::DEPENDENCIA_ID);        
    	 	$c->add(SeriePeer::SERIE_ID,$this->getRequestParameter('serie_id'));		
    		$this->parametros.="&serie_id=".$this->getRequestParameter('serie_id');			 	
        }
         
        if($this->getRequestParameter('tipodocumental_id')){
            $c->addJoin(DependenciaPeer::DEPENDENCIA_ID,SeriePeer::DEPENDENCIA_ID);
            $c->addJoin(SeriePeer::SERIE_ID,SubseriePeer::SERIE_ID);
            $c->addJoin(SubseriePeer::SUBSERIE_ID,TipoDocumentalPeer::SUBSERIE_ID);
    	 	$c->add(TipoDocumentalPeer::TIPODOCUMENTAL_ID,$this->getRequestParameter('tipodocumental_id'));		
    		$this->parametros.="&tipodocumental_id=".$this->getRequestParameter('tipodocumental_id');			 	
        }
         
      	if($this->getRequestParameter('orden')){
    	 	$c->addDescendingOrderByColumn(DependenciaPeer::$this->getRequestParameter('orden'));		
    		$this->parametros.="&orden=".$this->getRequestParameter('orden');			 	
    	}else{
    		$c->addAscendingOrderByColumn(DependenciaPeer::NOMBRE);
    	}
    	//****************************************************************************************************
    	if(!$this->getUser()->checkPerm("TRD_LISTAR_DEPENDENCIAS_TODAS_ENTIDADES", $usuariologuiado)){
    		$c->add(DependenciaPeer::ENTIDAD_ID,$entidad_conectado);
    	}
    	//****************************************************************************************************
        $pager=new sfPropelPager('Dependencia',15);
    	$pager->setCriteria($c);
    	$pager->setPage($this->getRequestParameter('page',1));
    	$pager->init();
    	$this->pager=$pager;
        $this->oficinaproductora_id = $oficinaproductora_id;
        $this->procesos_id = $procesos_id;
    }
    else
    {
        return $this->redirect($this->getRequest()->getScriptName().'/macro_proceso/list');
    }	
  }
  
  public function executeExcel()
  {
