  public function executeUpdate()
  {
    if (!$this->getRequestParameter('dependencia_id'))
    {
      $dependencia = new Dependencia();
    }
    else
    {
      $dependencia = DependenciaPeer::retrieveByPk($this->getRequestParameter('dependencia_id'));
      $this->forward404Unless($dependencia);
    }

    //$dependencia->setDependenciaId($this->getRequestParameter('dependencia_id'));
    $dependencia->setNombre($this->getRequestParameter('nombre'));
    $dependencia->setCodigo($this->getRequestParameter('codigo'));
    $dependencia->setTiempoPrestamo($this->getRequestParameter('tiempo_prestamo'));

    $dependencia->save();

    return $this->redirect($this->getRequest()->getScriptName().'/dependencia/show?dependencia_id='.$dependencia->getDependenciaId());
  }

  public function executeDelete()
  {
    $dependencia = DependenciaPeer::retrieveByPk($this->getRequestParameter('dependencia_id'));

    $this->forward404Unless($dependencia);

    $dependencia->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/dependencia/list');
  }
